import clsx from "clsx";
import { useApi } from "../../lib/data.js";
import { formatNumber, formatPercent } from "../../lib/format.js";
import { Item, Text } from "../ui/ds.jsx";

export default function MarketStrip() {
    const { data } = useApi("market/header.json");
    if (!data)
        return <Text className="inline-block h-4 w-80" />;
    return (
        <ul className="flex items-center gap-4" aria-label="Börse">
            {data.indices.map((index) => (
                <Item key={index.name} className="flex items-center gap-1.5">
                    <Text className="font-medium text-ink-700">{index.name}</Text>
                    <Text className="tabular-nums">{formatNumber(index.value)}</Text>
                    <Text className={clsx("font-bold tabular-nums", index.change >= 0 ? "text-ok-700" : "text-alert-700")}>{formatPercent(index.change)}</Text>
                </Item>
            ))}
        </ul>
    );
}
